codeExamples.code:
-- ANTI-PATTERN: forces counting ALL matching rows just to know if >0
SELECT CASE WHEN (SELECT COUNT(*) FROM orders WHERE customer_id = 100) > 0
            THEN 'has orders' ELSE 'no orders' END AS status;

-- BETTER: EXISTS stops at the first matching row
SELECT CASE WHEN EXISTS (SELECT 1 FROM orders WHERE customer_id = 100)
            THEN 'has orders' ELSE 'no orders' END AS status;

-- Common use: customers who have placed at least one order
SELECT c.customer_id, c.name
FROM customers c
WHERE EXISTS (
    SELECT 1 FROM orders o WHERE o.customer_id = c.customer_id
);
